/* Lot 111: opacity in math functions, var(), all, revert and revert-layer (generated by scripts/lot111_gen.py; expectations from scripts/lot111_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[2048];

static void prep(const char *css) {
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
}

/* the final opacity (1/10000) of the element with that id (body: the
 * body element), -1 when the reader passes none */
static int op_of(const char *id) {
    int i;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(id, "body") ? !strcmp(g_d.node[i].tag, "body") : !strcmp(g_d.node[i].id, id))
            return g_d.node[i].op_val >= 2 ? g_d.node[i].op : -1;
    return -2;
}

static void test_l111_op_0(void) {
    prep("@layer a, b; @layer b { #i { opacity: calc(var(--a) * 2) !important; opacity: calc(var(--p) + 10%) } } body { --a: 0.3 } #q { --a: 0.3 } @layer b { #o { opacity: min(var(--a), 0.3) } }");
    TEST_ASSERT_EQUAL(3000, op_of("o"));
    TEST_ASSERT_EQUAL(6000, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; @layer b { div { opacity: unset } } @layer a { div { opacity: inherit; all: inherit } } #o { --a: 1.5 }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #i { --a: 0.25 } @layer a { #q { opacity: calc(var(--b) / 2) } } @layer b { body { opacity: calc(1 / 0) } } #o { opacity: calc(var(--b) / 2) } @layer b { body { all: revert } } body { --a: 1.5 } #q { --a: 0.25 } @layer a { div { opacity: var(--n) } } #i { opacity: min(var(--a), 0.3) }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(2500, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; div { opacity: clamp(0, 0.35, 1); all: revert !important } #i { --a: 0.8; --b: calc(0.1 * 3); --p: 0.2 } #i { opacity: revert-layer } #q { opacity: calc(0.5) } @layer b { #o { opacity: var(--n, 0.4); opacity: 0.1 } } #o { opacity: min(1, calc(0.3 * 2)) } #o { --a: nonsense } @layer a { #o { opacity: 1 } }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(5000, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #q { all: revert-layer; all: initial } p { opacity: calc(1 - 0.75) } #o { --a: 40%; --b: nonsense } body { opacity: calc(0.5 + 10%) } @layer a { #q { opacity: 0.5; opacity: 0.5 } } #i { --a: calc(0.1 * 3); --b: 0.25 } @layer b { body { opacity: 0 } } body { --a: 0.3; --p: 35% }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(2500, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(0, op_of("body"));
    prep("@layer a, b; div { all: unset } div { opacity: 0.1 !important } @layer b { #i { opacity: 0.5; opacity: calc(2 * 30%) !important } }");
    TEST_ASSERT_EQUAL(1000, op_of("o"));
    TEST_ASSERT_EQUAL(6000, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #q { opacity: unset } #o { --a: nonsense } p { opacity: max(0.1, 50%) !important } #q { --a: nonsense }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #q { --a: 0.3 } body { --a: 40% } p { opacity: revert; opacity: calc(0.25 + 0.5) } #i { --a: 0.3; --p: 0.2 } p { all: revert } #i { all: initial } div { opacity: min(var(--a), 0.3) } @layer a { body { opacity: calc(var(--p) + 10%); opacity: min(1, calc(0.3 * 2)) } } @layer a { div { all: initial } }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(6000, op_of("body"));
    prep("@layer a, b; body { --a: 0.8 } #i { --a: 0.25 } p { opacity: 0.25 } #q { --a: calc(0.1 * 3); --b: 1.5 } @layer b { p { opacity: 0.25 } } #i { opacity: calc(0.5); opacity: unset } p { opacity: 70% }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(7000, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #q { --a: 0.8 } @layer b { div { opacity: calc(0.2 - 0.5) } } @layer a { div { all: unset; opacity: calc(1 / 0) } } @layer b { body { opacity: initial } } #i { --a: 1.5; --b: 0.8 } #q { all: revert-layer } @layer a { body { opacity: var(--a) } } body { --a: calc(0.1 * 3); --b: 0.25 } @layer a { #q { opacity: var(--b) } }");
    TEST_ASSERT_EQUAL(0, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(2500, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
}

static void test_l111_op_1(void) {
    prep("@layer a, b; @layer b { body { opacity: var(--n, var(--a)); opacity: revert } } #q { --a: 0.8 } @layer b { p { opacity: initial; opacity: calc(var(--b) / 2) } } #q { opacity: max(20%, 35%); opacity: revert-layer !important } @layer a { #o { all: initial } }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(3500, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; body { --a: nonsense; --p: 0.2 } #o { --a: 0.3 } @layer b { #o { opacity: calc(3 * 0.5) } } div { opacity: 70%; opacity: 0.25 } body { all: revert-layer }");
    TEST_ASSERT_EQUAL(2500, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #i { opacity: revert } #i { opacity: unset } #o { opacity: calc(var(--p) + 10%); opacity: 0.25 } body { --a: 0.3; --p: 35% } @layer b { #q { opacity: calc(3 * 0.5) } } #o { opacity: revert }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(10000, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #o { opacity: calc(var(--b) / 2); opacity: clamp(0, 0.35, 1) } body { --a: 0.25; --b: 0.25 } #o { --a: 1.5; --p: 20% } #o { opacity: revert-layer !important } #i { --a: nonsense; --b: 0.3; --p: 20% } div { opacity: 0.5 }");
    TEST_ASSERT_EQUAL(3500, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; @layer b { #q { all: revert-layer } } #i { opacity: var(--b) !important; all: unset } #q { opacity: revert-layer } #i { --a: calc(0.1 * 3); --b: calc(0.1 * 3) }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(3000, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; div { opacity: calc(0.5px) } @layer a { p { opacity: calc(var(--a) * 2); opacity: calc(0.25 + 0.5) } } @layer b { #q { opacity: revert; opacity: var(--b) } }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(7500, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #q { opacity: unset } @layer a { #q { opacity: 70%; opacity: calc(var(--b) / 2) } } #i { opacity: inherit } @layer b { #q { opacity: calc(3 * 0.5) } } #o { --a: 40%; --b: 0.8 } #i { opacity: var(--n, 0.4) }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(4000, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; body { all: unset } #o { --a: 0.3 } @layer b { body { opacity: inherit; opacity: unset } } #i { --a: 0.3; --b: 1.5 } p { opacity: unset } @layer b { p { opacity: calc(0.5) !important } }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(5000, op_of("i"));
    TEST_ASSERT_EQUAL(5000, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; @layer b { p { opacity: var(--b); opacity: calc(0.25 + 0.5) } } #o { opacity: var(--a); opacity: clamp(0, 0.35, 1) } body { --a: nonsense; --p: 0.2 } div { opacity: initial; opacity: revert } @layer a { #o { opacity: calc(var(--a) * 2) } } @layer b { div { opacity: revert-layer; opacity: inherit } }");
    TEST_ASSERT_EQUAL(3500, op_of("o"));
    TEST_ASSERT_EQUAL(7500, op_of("i"));
    TEST_ASSERT_EQUAL(7500, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; body { --a: 0.3 } @layer a { div { opacity: calc(var(--p) + 10%) } } body { all: unset !important; opacity: min(var(--a), 0.3) } @layer a { p { all: revert-layer !important; opacity: 0.25 } } #q { opacity: calc(0.5 + 10%); opacity: inherit }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(2500, op_of("i"));
    TEST_ASSERT_EQUAL(10000, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
}

static void test_l111_op_2(void) {
    prep("@layer a, b; @layer b { #q { opacity: var(--n, var(--a)) } } p { all: revert; opacity: calc(var(--a) * 2) } @layer b { #q { all: unset !important } } #o { --a: 0.25; --b: nonsense }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(5000, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #i { opacity: clamp(0, 0.35, 1) } div { all: revert-layer; opacity: clamp(10%, 50%, 40%) } #q { --a: 0.3; --b: nonsense; --p: 35% }");
    TEST_ASSERT_EQUAL(4000, op_of("o"));
    TEST_ASSERT_EQUAL(3500, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; div { opacity: 0.1; opacity: revert-layer } body { --a: calc(0.1 * 3) } #q { opacity: calc(1 - 0.75) }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(2500, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; div { all: revert-layer } @layer b { #i { opacity: min(0.2, 0.7) } } @layer a { #i { all: revert-layer } } #q { --a: 0.25; --b: 0.3 } @layer b { #q { opacity: inherit } } #i { opacity: initial }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(10000, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #i { opacity: 1 } #o { --a: nonsense; --b: 0.3 } div { opacity: 1 } @layer b { #i { opacity: var(--a) } } body { --a: nonsense; --b: calc(0.1 * 3) }");
    TEST_ASSERT_EQUAL(10000, op_of("o"));
    TEST_ASSERT_EQUAL(10000, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; @layer b { body { opacity: 0.5; opacity: clamp(0, 0.35, 1) !important } } body { all: inherit; opacity: initial } div { all: revert }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(3500, op_of("body"));
    prep("@layer a, b; @layer a { body { all: inherit; opacity: min(var(--a), 0.3) !important } } @layer a { #i { opacity: calc(0.25 + 0.5); opacity: initial } } @layer a { #i { opacity: 70%; opacity: var(--b) } } #i { opacity: calc(0.25 + 0.5) } @layer a { #o { opacity: revert !important } } #i { --a: 0.3 } div { opacity: 0.25 !important }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(7500, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(10000, op_of("body"));
    prep("@layer a, b; @layer a { body { opacity: calc(50% / 4) } } @layer a { #o { opacity: calc((0.1 + 0.2) * 2); opacity: unset } } body { --a: 0.25 } p { opacity: var(--a, 0.5) } body { all: initial } #o { --a: 0.3 }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(3000, op_of("i"));
    TEST_ASSERT_EQUAL(2500, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #o { opacity: calc(0.25 + 0.5) } #i { all: initial } #o { --a: 0.3; --b: nonsense } @layer b { p { opacity: revert } }");
    TEST_ASSERT_EQUAL(7500, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; @layer a { #q { opacity: inherit } } @layer a { body { opacity: revert } } body { opacity: calc(0.5) } body { --a: 0.3; --b: 40%; --p: 35% } #q { --a: nonsense; --b: nonsense } @layer b { body { opacity: var(--b) } } #o { opacity: calc(0.5 + 10%); opacity: 0.5 }");
    TEST_ASSERT_EQUAL(5000, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(5000, op_of("q"));
    TEST_ASSERT_EQUAL(5000, op_of("body"));
}

static void test_l111_op_3(void) {
    prep("@layer a, b; div { opacity: initial !important; opacity: max(0.1, 50%) } p { opacity: calc(1 / 0) } @layer a { #q { all: initial } } body { opacity: revert } #o { opacity: calc(30% * 2) } @layer a { body { all: inherit } }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #q { --a: 0.3; --b: 0.8; --p: 35% } body { --a: calc(0.1 * 3) } @layer b { #q { opacity: calc(-1 * 20%) } } @layer b { div { opacity: 0.1; opacity: calc(-1 * 20%) } } @layer a { body { opacity: var(--n, var(--a)) } } div { opacity: var(--a, 0.5); opacity: 0.25 !important }");
    TEST_ASSERT_EQUAL(2500, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(0, op_of("q"));
    TEST_ASSERT_EQUAL(3000, op_of("body"));
    prep("@layer a, b; @layer a { #i { opacity: var(--a) } } #i { opacity: 0; all: initial !important } #q { opacity: initial } #i { --a: 40% } p { opacity: initial; opacity: calc(var(--b) / 2) } #q { opacity: revert; all: inherit }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(10000, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; @layer b { p { opacity: max(20%, 35%) } } body { --a: 1.5; --b: 0.25; --p: 20% } body { opacity: var(--b); opacity: 0 } #q { --a: nonsense; --b: 1.5 } body { opacity: min(1, calc(0.3 * 2)) } div { all: unset } div { opacity: 0.5 }");
    TEST_ASSERT_EQUAL(5000, op_of("o"));
    TEST_ASSERT_EQUAL(3500, op_of("i"));
    TEST_ASSERT_EQUAL(3500, op_of("q"));
    TEST_ASSERT_EQUAL(6000, op_of("body"));
    prep("@layer a, b; #q { all: inherit } #i { opacity: calc(0.5 + 10%); opacity: 0.25 }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(2500, op_of("i"));
    TEST_ASSERT_EQUAL(10000, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #i { opacity: 0.5; all: revert } @layer b { #i { opacity: max(0.1, 50%); opacity: calc(var(--a) * 2) !important } } @layer a { p { opacity: calc(0.5px) } } body { opacity: revert-layer !important; opacity: revert-layer } #q { opacity: var(--b) } body { --a: 0.8 }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(10000, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; body { --a: 0.25; --p: 20% } @layer b { body { opacity: initial !important; all: inherit } } #o { opacity: min(0.2, 0.7) }");
    TEST_ASSERT_EQUAL(2000, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; @layer a { div { opacity: calc(2 * 30%) } } #i { opacity: calc(10% * 10%) } p { opacity: calc(var(--b) / 2) !important; opacity: var(--n) } #q { opacity: revert } @layer b { #o { opacity: clamp(10%, 50%, 40%) !important } } @layer b { div { opacity: min(0.2, 0.7) } }");
    TEST_ASSERT_EQUAL(4000, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; #q { opacity: var(--a, 0.5) } #q { --a: 0.8; --b: 0.25 } body { opacity: unset } #o { --a: 0.3 } @layer b { body { opacity: 0 } }");
    TEST_ASSERT_EQUAL(-1, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(8000, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
    prep("@layer a, b; body { opacity: revert } #o { opacity: 0; opacity: revert } #o { opacity: 0.1 } #o { --a: 40% } @layer a { div { opacity: calc(0.5px) } } @layer b { p { opacity: initial } } @layer a { body { opacity: unset } }");
    TEST_ASSERT_EQUAL(1000, op_of("o"));
    TEST_ASSERT_EQUAL(-1, op_of("i"));
    TEST_ASSERT_EQUAL(-1, op_of("q"));
    TEST_ASSERT_EQUAL(-1, op_of("body"));
}

